#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> board(n, vector<long long>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> board[i][j];
        }
    }

    long long total = n * n;
    vector<long long> dist(total + 1, -1);
    dist[1] = 0;
    vector<long long> queue = {1};
    for (size_t i = 0; i < queue.size(); i++) {
        long long s = queue[i];
        for (long long t = s + 1; t <= min(s + 6, total); t++) {
            long long rowFromBottom = (t - 1) / n;
            long long col = (t - 1) % n;
            if (rowFromBottom % 2 == 1) col = n - 1 - col;
            long long value = board[n - 1 - rowFromBottom][col];
            long long next = value != -1 ? value : t;
            if (dist[next] < 0) {
                dist[next] = dist[s] + 1;
                queue.push_back(next);
            }
        }
    }
    cout << dist[total] << "\n";

    return 0;
}

