import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] board = new long[(int) n][(int) n];
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                board[i][j] = Long.parseLong(next());
            }
        }

        int size = (int) n;
        int total = size * size;
        int[] dist = new int[total + 1];
        Arrays.fill(dist, -1);
        dist[1] = 0;
        List<Integer> queue = new ArrayList<>();
        queue.add(1);
        for (int i = 0; i < queue.size(); i++) {
            int s = queue.get(i);
            for (int t = s + 1; t <= Math.min(s + 6, total); t++) {
                int rowFromBottom = (t - 1) / size;
                int col = (t - 1) % size;
                if (rowFromBottom % 2 == 1) col = size - 1 - col;
                long value = board[size - 1 - rowFromBottom][col];
                int next = value != -1 ? (int) value : t;
                if (dist[next] < 0) {
                    dist[next] = dist[s] + 1;
                    queue.add(next);
                }
            }
        }
        System.out.println(dist[total]);
    }
}
